class LedgerTotals {
    private val lock = Any()
    private var totalCents = 0L   // guarded by lock

    fun add(cents: Long) {
        synchronized(lock) { totalCents += cents }
    }

    // hb: same lock object on both sides
    fun total(): Long = synchronized(lock) { totalCents }
}

