public final class OneShot<T> {
    private final CountDownLatch done = new CountDownLatch(1);
    private T value;   // plain: the latch orders it

    public void set(T v) {
        value = v;          // 1. write
        done.countDown();   // 2. release
    }

    // hb: actions before countDown() happen-before actions after await() returns
    public T get() throws InterruptedException {
        done.await();       // 3. acquire
        return value;       // 4. sees the write from step 1
    }
}

