class OneShot<T> {
    private val done = CountDownLatch(1)
    private var value: T? = null   // plain: the latch orders it

    fun set(v: T) {
        value = v          // 1. write
        done.countDown()   // 2. release
    }

    // hb: actions before countDown() happen-before actions after await() returns
    fun get(): T {
        done.await()       // 3. acquire
        @Suppress("UNCHECKED_CAST")
        return value as T  // 4. sees the write from step 1
    }
}
